package com.dymbia.sumaqagro.platform.farming.domain.model.commands;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Command to record the purchase of seeds, fertilizers or pesticides in a cost ledger.
 *
 * @param campaignLedgerId the ledger of the campaign
 * @param inputName        the input bought, such as "Urea"
 * @param quantity         the quantity bought
 * @param unitPrice        the price of one unit
 * @param expenseDate      the date of the purchase
 * @param clientSyncId     the id generated by the device in offline mode, optional
 */
public record RecordInputExpenseCommand(Long campaignLedgerId, String inputName, BigDecimal quantity,
                                        BigDecimal unitPrice, LocalDate expenseDate, String clientSyncId) {
    public RecordInputExpenseCommand {
        if (campaignLedgerId == null || campaignLedgerId <= 0) {
            throw new IllegalArgumentException("campaign.ledger.error.id.invalid");
        }
    }
}
